<?php

// Settings for the offline PEQ → JSON data pipeline (the eq:* Artisan commands). The site itself is
// static and reads only the committed database/eq/*.json; its runtime tuning lives in src/config.js.
return [

    // Committed JSON graph the site bundles. Regenerated by `php artisan eq:build-graph`.
    'graph_path' => database_path('eq/graph.json'),

    // Player races → EQEmu numeric ids. eq:build-factions uses them to find factions whose standing
    // spread across races can make a zone KOS (see factions.json). Mirrored in src/config.js, which
    // also carries classes/deities for the browser-side KOS math.
    'races' => [
        'HUM' => ['label' => 'Human', 'id' => 1],
        'BAR' => ['label' => 'Barbarian', 'id' => 2],
        'ERU' => ['label' => 'Erudite', 'id' => 3],
        'ELF' => ['label' => 'Wood Elf', 'id' => 4],
        'HIE' => ['label' => 'High Elf', 'id' => 5],
        'DEF' => ['label' => 'Dark Elf', 'id' => 6],
        'HEF' => ['label' => 'Half Elf', 'id' => 7],
        'DWF' => ['label' => 'Dwarf', 'id' => 8],
        'TRL' => ['label' => 'Troll', 'id' => 9],
        'OGR' => ['label' => 'Ogre', 'id' => 10],
        'HFL' => ['label' => 'Halfling', 'id' => 11],
        'GNM' => ['label' => 'Gnome', 'id' => 12],
        'IKS' => ['label' => 'Iksar', 'id' => 128],
        'VAH' => ['label' => 'Vah Shir', 'id' => 130],
        'FRG' => ['label' => 'Froglok', 'id' => 330],
        'DRK' => ['label' => 'Drakkin', 'id' => 522],
    ],

    // Committed faction data (built by eq:build-factions): per-zone guard factions + their
    // base/modifiers. The browser router computes standing and flags KOS legs from it.
    'factions_path' => database_path('eq/factions.json'),

    // Con standing at or below which a faction is kill-on-sight. -750 is EQEmu's THREATENINGLY
    // boundary — a mob at exactly -750 already attacks on sight (only -751+ is "Scowls"), so the
    // comparison is inclusive (<=).
    'kos_threshold' => -750,

    // Minimum spawn points a guard faction must have in a zone before it counts toward KOS. Filters
    // out a single stray patrol wandering into a dungeon (e.g. one Qeynos guard in Blackburrow) so the
    // zone isn't flagged "guards KOS" off one NPC. Used by eq:build-factions.
    'kos_min_spawns' => 2,

    // DB connection holding an imported PEQ dump. Used by eq:build-graph, eq:build-factions, and
    // the eq:import-peq command that populates it.
    'connection' => env('PEQ_CONNECTION', 'peq'),

    // ProjectEQ content-database dump (a zip of mariadb-dump SQL). eq:import-peq downloads this,
    // slices out just `import_tables`, and loads them into the `connection` above.
    'dump_url' => env('PEQ_DUMP_URL', 'https://db.eqemu.dev/api/v1/dump/latest'),

    // The only PEQ tables we need: zones/connections/spells for the graph, faction/spawn for KOS.
    'import_tables' => [
        'zone', 'zone_points', 'spells_new',
        'faction_list', 'faction_list_mod', 'npc_faction', 'npc_faction_entries',
        'npc_types', 'spawn2', 'spawnentry', 'spawngroup',
    ],

    // zone_points carries no travel type, so eq:build-graph defaults its edges to "walk". But the
    // hub zones below aren't reached on foot — Plane of Knowledge is book travel, the Nexus is
    // spire travel — so any zone_point touching one is retyped. Order matters: the first hub that
    // matches wins, so a Nexus↔PoK link is a spire, not a book.
    'zone_point_hubs' => [
        'nexus' => 'spire',
        'poknowledge' => 'book',
    ],

    // Sea crossings that zone_points mislabels as "walk" (you cross water between landmasses by
    // boat). eq:build-graph retypes the walk edge between each pair to "boat", keeping its coords.
    // Pairs are unordered. Verified against EQAtlas / the P99 wiki; add more as the audit finds them
    // (see eq:audit-graph). Distinct from a dangling junk zone_point, which is removed via overrides.
    'boat_links' => [
        ['nro', 'iceclad'],         // classic Velious boat: North Ro ⇄ Iceclad Ocean (P99 access)
        ['northro', 'iceclad'],     // Prophecy-of-Ro revamp of the same crossing
        ['butcher', 'oot'],         // Faydwer ⇄ Antonica: Butcherblock ⇄ Ocean of Tears
        ['erudsxing', 'qeynos2'],   // Antonica ⇄ Odus ferry: docks at North Qeynos (Mermaid's Lure), not South. P99-verified, no land route
        ['erudsxing', 'erudnext'],  // Erud's Crossing ⇄ Erudin (the ferry's Odus dock)
        ['timorous', 'firiona'],    // Kunark: Timorous Deep ⇄ Firiona Vie (reverse of an existing boat)
        ['timorous', 'overthere'],  // Kunark: Timorous Deep ⇄ The Overthere (reverse of an existing boat)
    ],

    // Anchor zones per classic landmass. eq:build-continents walks the classic-era (expansion ≤ 2)
    // land graph and labels each connected component by the continent whose anchor it contains, then
    // writes continents.json. A component with no anchor (e.g. a boat-only island) is left unlabeled;
    // a component with two different anchors means a bogus land edge still merges them (build warns).
    'continent_anchors' => [
        'Antonica' => ['qeynos', 'freportw', 'oasis', 'halas', 'nektulos'],
        'Faydwer' => ['gfaydark', 'akanon', 'butcher', 'kaladima'],
        'Odus' => ['erudnext', 'paineel', 'tox'],
        'Kunark' => ['cabeast', 'overthere', 'fieldofbone'],
        'Velious' => ['thurgadina', 'iceclad', 'greatdivide'],
    ],

    // Committed zone → continent map (built by eq:build-continents from the classic land graph).
    'continents_path' => database_path('eq/continents.json'),

    // Directory of Brewall map .txt files (https://www.eqmaps.info). Used by eq:build-graph to
    // add boats/spires/books and backfill zone-line coordinates. Not committed (licensing); drop
    // the unzipped maps here. Build skips Brewall gracefully when the dir is absent.
    'brewall_path' => env('BREWALL_PATH', storage_path('app/eq/maps')),

    // Goodurden map set (https://github.com/RedGuides/goodurden-maps — "Good's Maps" folder),
    // same lowercase `{zone}.txt` format. Used only as a per-zone fallback when Brewall lacks a
    // map (or ships an empty file). Drop the unzipped "Good's Maps" contents here.
    'goodurden_path' => env('GOODURDEN_PATH', storage_path('app/eq/maps-goodurden')),

];
